items.solution:
function createAuditLog() {
  const entries = [];
  return {
    record(actor, action, timestamp) {
      entries.push({ actor, action, timestamp });
    },
    entriesFor(actor) {
      return entries.filter((e) => e.actor === actor);
    },
  };
}

